===== 001_init =====
-- Enable pgcrypto for gen_random_uuid
create extension if not exists pgcrypto;

-- Receipts table
create table if not exists public.receipts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  receipt_image_path text,
  transaction_date date,
  total_amount numeric,
  tax numeric,
  merchant_name text,
  credit_card_name text,
  credit_card_last_4 text,
  currency text,
  created_at timestamptz not null default now()
);

alter table public.receipts enable row level security;

-- Policies: users can access their own receipts
create policy "Users can view their receipts" on public.receipts
for select using (auth.uid() = user_id);

create policy "Users can insert their receipts" on public.receipts
for insert with check (auth.uid() = user_id) -- user_id must match auth.uid()
;

create policy "Users can update their receipts" on public.receipts
for update using (auth.uid() = user_id) with check (auth.uid() = user_id);

create policy "Users can delete their receipts" on public.receipts
for delete using (auth.uid() = user_id);

-- Allow setting user_id automatically via trigger
create or replace function public.set_receipt_user_id()
returns trigger language plpgsql as $$
begin
  if (new.user_id is null) then
    new.user_id := auth.uid();
  end if;
  return new;
end; $$;

create trigger set_receipt_user_id_before_insert
before insert on public.receipts
for each row execute procedure public.set_receipt_user_id();

-- Storage policies for 'receipts' bucket
-- Assumes a storage bucket named 'receipts' is created separately
-- Drop existing policies if they exist
DO $$
BEGIN
  DROP POLICY IF EXISTS "Receipts bucket read own" ON storage.objects;
  DROP POLICY IF EXISTS "Receipts bucket insert own" ON storage.objects;
  DROP POLICY IF EXISTS "Receipts bucket update own" ON storage.objects;
  DROP POLICY IF EXISTS "Receipts bucket delete own" ON storage.objects;
EXCEPTION
  WHEN undefined_object THEN NULL;
END $$;

-- Create storage policies (without IF NOT EXISTS since it's not supported)
CREATE POLICY "Receipts bucket read own" ON storage.objects
FOR SELECT USING (
  bucket_id = 'receipts' AND (auth.uid()::text = split_part(name, '/', 1))
);

CREATE POLICY "Receipts bucket insert own" ON storage.objects
FOR INSERT WITH CHECK (
  bucket_id = 'receipts' AND (auth.uid()::text = split_part(name, '/', 1))
);

CREATE POLICY "Receipts bucket update own" ON storage.objects
FOR UPDATE USING (
  bucket_id = 'receipts' AND (auth.uid()::text = split_part(name, '/', 1))
) WITH CHECK (
  bucket_id = 'receipts' AND (auth.uid()::text = split_part(name, '/', 1))
);

CREATE POLICY "Receipts bucket delete own" ON storage.objects
FOR DELETE USING (
  bucket_id = 'receipts' AND (auth.uid()::text = split_part(name, '/', 1))
);
===== 002_profiles_table =====
-- Profile table for additional email addresses
create table if not exists public.profiles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  email_1 text,
  email_2 text,
  email_3 text,
  email_4 text,
  email_5 text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint unique_user_id unique (user_id)
);

-- Add indexes for email lookups
create index if not exists profiles_email_1_idx on public.profiles(email_1) where email_1 is not null;
create index if not exists profiles_email_2_idx on public.profiles(email_2) where email_2 is not null;
create index if not exists profiles_email_3_idx on public.profiles(email_3) where email_3 is not null;
create index if not exists profiles_email_4_idx on public.profiles(email_4) where email_4 is not null;
create index if not exists profiles_email_5_idx on public.profiles(email_5) where email_5 is not null;

-- Enable RLS
alter table public.profiles enable row level security;

-- Policies: users can only access their own profile
create policy "Users can view their own profile" on public.profiles
for select using (auth.uid() = user_id);

create policy "Users can insert their own profile" on public.profiles
for insert with check (auth.uid() = user_id);

create policy "Users can update their own profile" on public.profiles
for update using (auth.uid() = user_id) with check (auth.uid() = user_id);

create policy "Users can delete their own profile" on public.profiles
for delete using (auth.uid() = user_id);

-- Trigger to update updated_at timestamp
create or replace function public.update_updated_at_column()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end; $$;

create trigger update_profiles_updated_at
before update on public.profiles
for each row execute procedure public.update_updated_at_column();

-- Helper function to find user_id by email (checks both auth.users and profiles)
-- This function is used by the service role, so it needs to be SECURITY DEFINER
create or replace function public.find_user_by_email(email_address text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  user_uuid uuid;
begin
  -- First check auth.users primary email
  select id into user_uuid
  from auth.users
  where lower(email) = lower(email_address)
  limit 1;

  if user_uuid is not null then
    return user_uuid;
  end if;

  -- Check profile emails
  select user_id into user_uuid
  from public.profiles
  where lower(email_1) = lower(email_address)
     or lower(email_2) = lower(email_address)
     or lower(email_3) = lower(email_address)
     or lower(email_4) = lower(email_address)
     or lower(email_5) = lower(email_address)
  limit 1;

  return user_uuid;
end;
$$;
===== 003_insert_receipt_rpc =====
-- RPC function to insert receipts with proper user context
-- This bypasses the ensure_default_family() trigger issue when using service role

-- First, ensure the family_members table exists and has the is_default column
DO $$
BEGIN
  -- Check if family_members table exists
  IF EXISTS (SELECT FROM pg_tables WHERE schemaname = 'public' AND tablename = 'family_members') THEN
    -- Add is_default column if it doesn't exist
    IF NOT EXISTS (
      SELECT FROM information_schema.columns
      WHERE table_schema = 'public'
      AND table_name = 'family_members'
      AND column_name = 'is_default'
    ) THEN
      ALTER TABLE public.family_members ADD COLUMN is_default boolean DEFAULT false;
    END IF;
  END IF;
END $$;

-- Create the insert function that sets proper user context
CREATE OR REPLACE FUNCTION insert_receipt_with_context(receipt_data jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  inserted_receipt jsonb;
  user_id_val uuid;
  receipt_id uuid;
BEGIN
  -- Extract user_id from the receipt_data
  user_id_val := (receipt_data->>'user_id')::uuid;

  -- Validate that user exists
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = user_id_val) THEN
    RAISE EXCEPTION 'User does not exist: %', user_id_val;
  END IF;

  -- Set the local session variable for auth.uid()
  -- This allows triggers and policies that depend on auth.uid() to work
  PERFORM set_config('request.jwt.claims', json_build_object('sub', user_id_val)::text, true);

  -- Insert the receipt
  INSERT INTO receipts (
    user_id,
    receipt_image_path,
    merchant_name,
    total_amount,
    tax,
    transaction_date,
    currency,
    credit_card_name,
    credit_card_last_4
  )
  VALUES (
    user_id_val,
    receipt_data->>'receipt_image_path',
    receipt_data->>'merchant_name',
    CASE WHEN receipt_data->>'total_amount' IS NOT NULL
      THEN (receipt_data->>'total_amount')::numeric
      ELSE NULL
    END,
    CASE WHEN receipt_data->>'tax' IS NOT NULL
      THEN (receipt_data->>'tax')::numeric
      ELSE NULL
    END,
    CASE WHEN receipt_data->>'transaction_date' IS NOT NULL
      THEN (receipt_data->>'transaction_date')::date
      ELSE NULL
    END,
    receipt_data->>'currency',
    receipt_data->>'credit_card_name',
    receipt_data->>'credit_card_last_4'
  )
  RETURNING id INTO receipt_id;

  -- Fetch and return the complete inserted receipt
  SELECT to_jsonb(receipts.*) INTO inserted_receipt
  FROM receipts
  WHERE id = receipt_id;

  RETURN inserted_receipt;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error and re-raise
    RAISE NOTICE 'Error in insert_receipt_with_context: % %', SQLERRM, SQLSTATE;
    RAISE;
END;
$$;

-- Grant execute permission to authenticated users and service role
GRANT EXECUTE ON FUNCTION insert_receipt_with_context(jsonb) TO authenticated, service_role, anon;

-- Add comment for documentation
COMMENT ON FUNCTION insert_receipt_with_context(jsonb) IS
'Inserts a receipt with proper user context. This function sets the JWT claims to allow triggers that depend on auth.uid() to function correctly when called from service role context.';
===== 006_add_is_default_to_family_members =====
-- Migration to add is_default column to family_members table
-- This resolves the "column fm.is_default does not exist" error

-- Add is_default column if table and column don't exist
DO $$
BEGIN
  -- Check if family_members table exists first
  IF EXISTS (
    SELECT FROM pg_tables
    WHERE schemaname = 'public'
    AND tablename = 'family_members'
  ) THEN
    -- Add is_default column if it doesn't exist
    IF NOT EXISTS (
      SELECT FROM information_schema.columns
      WHERE table_schema = 'public'
      AND table_name = 'family_members'
      AND column_name = 'is_default'
    ) THEN
      ALTER TABLE public.family_members
      ADD COLUMN is_default boolean DEFAULT false NOT NULL;

      RAISE NOTICE 'Added is_default column to family_members table';
    ELSE
      RAISE NOTICE 'is_default column already exists in family_members table';
    END IF;

    -- Add role column if it doesn't exist (needed by ensure_default_family function)
    IF NOT EXISTS (
      SELECT FROM information_schema.columns
      WHERE table_schema = 'public'
      AND table_name = 'family_members'
      AND column_name = 'role'
    ) THEN
      ALTER TABLE public.family_members
      ADD COLUMN role text DEFAULT 'member' NOT NULL;

      RAISE NOTICE 'Added role column to family_members table';
    ELSE
      RAISE NOTICE 'role column already exists in family_members table';
    END IF;

    -- Ensure there's at least one default family member per user
    -- Update the first family member for each user to be default if none exist
    UPDATE public.family_members fm1
    SET is_default = true
    WHERE (fm1.family_id, fm1.user_id) IN (
      SELECT DISTINCT ON (user_id) family_id, user_id
      FROM public.family_members
      WHERE user_id NOT IN (
        SELECT DISTINCT user_id
        FROM public.family_members
        WHERE is_default = true
      )
      ORDER BY user_id, family_id
    );

    RAISE NOTICE 'Set default family members for users without defaults';

    -- Add index for better performance on is_default lookups
    IF NOT EXISTS (
      SELECT 1 FROM pg_indexes
      WHERE schemaname = 'public'
      AND tablename = 'family_members'
      AND indexname = 'idx_family_members_user_id_is_default'
    ) THEN
      CREATE INDEX idx_family_members_user_id_is_default
      ON public.family_members(user_id, is_default)
      WHERE is_default = true;

      RAISE NOTICE 'Created index on family_members(user_id, is_default)';
    END IF;

    -- Add comments for documentation
    COMMENT ON COLUMN public.family_members.is_default IS
    'Indicates whether this is the default family membership for the user. Used to automatically assign receipts to a family when none is specified.';

    COMMENT ON COLUMN public.family_members.role IS
    'The role of the user in the family (e.g., owner, member, admin).';
  ELSE
    RAISE NOTICE 'family_members table does not exist - skipping migration';
  END IF;
END $$;
