-- Create transactions table for credit card and bank reconciliation
create table if not exists public.transactions (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references public.families(id) on delete cascade,
  transaction_date date not null,
  vendor_name text not null,
  amount numeric not null,
  credit_card_type text not null,
  ignored boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Create index for faster queries
create index if not exists idx_transactions_family_id on public.transactions(family_id);
create index if not exists idx_transactions_date on public.transactions(transaction_date);
create index if not exists idx_transactions_credit_card_type on public.transactions(credit_card_type);

-- Enable RLS
alter table public.transactions enable row level security;

-- RLS Policies: users can access transactions for families they belong to
create policy "Users can view family transactions" on public.transactions
for select using (
  exists (
    select 1 from public.family_members fm
    where fm.family_id = transactions.family_id
    and fm.user_id = auth.uid()
  )
);

create policy "Users can insert family transactions" on public.transactions
for insert with check (
  exists (
    select 1 from public.family_members fm
    where fm.family_id = transactions.family_id
    and fm.user_id = auth.uid()
  )
);

create policy "Users can update family transactions" on public.transactions
for update using (
  exists (
    select 1 from public.family_members fm
    where fm.family_id = transactions.family_id
    and fm.user_id = auth.uid()
  )
) with check (
  exists (
    select 1 from public.family_members fm
    where fm.family_id = transactions.family_id
    and fm.user_id = auth.uid()
  )
);

create policy "Users can delete family transactions" on public.transactions
for delete using (
  exists (
    select 1 from public.family_members fm
    where fm.family_id = transactions.family_id
    and fm.user_id = auth.uid()
  )
);

-- Trigger to update updated_at timestamp
create or replace function public.update_transactions_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end; $$;

create trigger update_transactions_updated_at_trigger
before update on public.transactions
for each row execute procedure public.update_transactions_updated_at();

-- Create unique constraint to prevent duplicate transactions
-- Using transaction_date, vendor_name, amount, credit_card_type, and family_id
create unique index if not exists idx_transactions_unique
on public.transactions(family_id, transaction_date, vendor_name, amount, credit_card_type);
===== 008_add_receipt_transaction_matching =====
-- Add matched_transaction_id to receipts table for reconciliation
alter table public.receipts
add column if not exists matched_transaction_id uuid references public.transactions(id) on delete set null;

-- Create index for faster matching queries
create index if not exists idx_receipts_matched_transaction_id on public.receipts(matched_transaction_id);

-- Create index for unmatched receipts (where matched_transaction_id is null)
create index if not exists idx_receipts_unmatched on public.receipts(matched_transaction_id) where matched_transaction_id is null;

-- Create index for receipts by date range for faster reconciliation queries
create index if not exists idx_receipts_transaction_date on public.receipts(transaction_date) where transaction_date is not null;

-- Add is_duplicate flag to receipts for flagging potential duplicates
alter table public.receipts
add column if not exists is_duplicate boolean not null default false;

-- Create index for duplicate flagged receipts
create index if not exists idx_receipts_is_duplicate on public.receipts(is_duplicate);

-- Function to find potential duplicate receipts
-- Two receipts are potential duplicates if they have:
-- - Same or very similar amounts (within $0.01)
-- - Same merchant name (case-insensitive)
-- - Same date or within 1 day
create or replace function public.find_duplicate_receipts(
  p_receipt_id uuid,
  p_user_id uuid,
  p_transaction_date date,
  p_merchant_name text,
  p_total_amount numeric
)
returns table(duplicate_receipt_id uuid, similarity_score numeric)
language plpgsql as $$
begin
  return query
  select
    r.id as duplicate_receipt_id,
    -- Calculate similarity score (higher is more similar)
    (
      case when abs(r.total_amount - p_total_amount) <= 0.01 then 1.0 else 0.5 end +
      case when lower(r.merchant_name) = lower(p_merchant_name) then 1.0 else 0.0 end +
      case when r.transaction_date = p_transaction_date then 1.0
           when abs(r.transaction_date - p_transaction_date) <= 1 then 0.5
           else 0.0 end
    ) as similarity_score
  from public.receipts r
  where r.id != p_receipt_id
    and r.user_id = p_user_id
    and r.transaction_date is not null
    and r.total_amount is not null
    and r.merchant_name is not null
    and abs(r.total_amount - p_total_amount) <= 1.0  -- Within $1
    and abs(r.transaction_date - p_transaction_date) <= 3  -- Within 3 days
  order by similarity_score desc
  limit 5;
end; $$;

-- Grant execute permission to authenticated users
grant execute on function public.find_duplicate_receipts(uuid, uuid, date, text, numeric) to authenticated;
===== 010_expense_categorization =====
-- Migration: Expense Categorization System
-- Specification: #{#exp1b} - Expenses Derived from Receipts
-- Authority: system
-- Priority: Critical
--
-- This migration creates the database schema for expense categorization:
-- 1. categories - User-defined expense categories
-- 2. expense_categories - Receipt to category mapping (1:1)
-- 3. vendor_category_rules - Auto-categorization rules based on vendor names
--
-- Expenses are derived views from receipts, not separate entities.

-- ============================================================================
-- Table: categories
-- Purpose: Store user-defined expense categories
-- Specification: #{#exp3a} - User Category Management
-- ============================================================================

CREATE TABLE IF NOT EXISTS categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name VARCHAR(100) NOT NULL,
  color VARCHAR(7), -- Hex color code, e.g., #FF5733
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Unique constraint on user_id and case-insensitive name
CREATE UNIQUE INDEX IF NOT EXISTS unique_category_per_user ON categories(user_id, LOWER(name));

-- Index for efficient user-specific queries
CREATE INDEX IF NOT EXISTS idx_categories_user_id ON categories(user_id);

-- ============================================================================
-- Table: expense_categories
-- Purpose: Map receipts to categories (1:1 relationship)
-- Specification: #{#exp1b} - Expenses Derived from Receipts
-- ============================================================================

CREATE TABLE IF NOT EXISTS expense_categories (
  receipt_id UUID PRIMARY KEY REFERENCES receipts(id) ON DELETE CASCADE,
  category_id UUID REFERENCES categories(id) ON DELETE SET NULL,
  categorization_source VARCHAR(10) NOT NULL CHECK (categorization_source IN ('manual', 'auto')),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for efficient queries
CREATE INDEX IF NOT EXISTS idx_expense_categories_category ON expense_categories(category_id);
CREATE INDEX IF NOT EXISTS idx_expense_categories_source ON expense_categories(categorization_source);

-- ============================================================================
-- Table: vendor_category_rules
-- Purpose: Auto-categorization rules based on vendor patterns
-- Specification: #{#exp4a} - Automatic Category Assignment via Vendor Rules
-- ============================================================================

CREATE TABLE IF NOT EXISTS vendor_category_rules (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  vendor_pattern VARCHAR(200) NOT NULL, -- Normalized merchant name pattern
  category_id UUID NOT NULL REFERENCES categories(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT unique_vendor_rule_per_user UNIQUE(user_id, vendor_pattern)
);

-- Index for efficient user-specific queries
CREATE INDEX IF NOT EXISTS idx_vendor_rules_user_id ON vendor_category_rules(user_id);

-- ============================================================================
-- Row-Level Security (RLS) Policies
-- Purpose: Ensure users can only access their own data
-- ============================================================================

-- Enable RLS on all tables
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE expense_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE vendor_category_rules ENABLE ROW LEVEL SECURITY;

-- Categories: Users can only access their own categories
CREATE POLICY categories_user_isolation ON categories
  FOR ALL USING (auth.uid() = user_id);

-- Expense Categories: Users can only access categories for their own receipts
CREATE POLICY expense_categories_user_isolation ON expense_categories
  FOR ALL USING (
    receipt_id IN (SELECT id FROM receipts WHERE user_id = auth.uid())
  );

-- Vendor Rules: Users can only access their own vendor rules
CREATE POLICY vendor_rules_user_isolation ON vendor_category_rules
  FOR ALL USING (auth.uid() = user_id);

-- ============================================================================
-- Function: Create Default Categories for New Users
-- Purpose: Automatically create default categories when user signs up
-- Specification: #{#exp3a} - User Category Management
-- ============================================================================

CREATE OR REPLACE FUNCTION create_default_categories(p_user_id UUID)
RETURNS VOID AS $$
BEGIN
  -- Insert default categories for new user
  INSERT INTO categories (user_id, name, color) VALUES
    (p_user_id, 'Groceries', '#10B981'),
    (p_user_id, 'Dining', '#F59E0B'),
    (p_user_id, 'Transportation', '#3B82F6'),
    (p_user_id, 'Entertainment', '#8B5CF6'),
    (p_user_id, 'Healthcare', '#EF4444'),
    (p_user_id, 'Shopping', '#EC4899'),
    (p_user_id, 'Utilities', '#6366F1'),
    (p_user_id, 'Travel', '#14B8A6'),
    (p_user_id, 'Other', '#6B7280')
  ON CONFLICT (user_id, LOWER(name)) DO NOTHING;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- Trigger: Update updated_at timestamp on record changes
-- ============================================================================

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply trigger to all tables
CREATE TRIGGER update_categories_updated_at
  BEFORE UPDATE ON categories
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_expense_categories_updated_at
  BEFORE UPDATE ON expense_categories
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_vendor_rules_updated_at
  BEFORE UPDATE ON vendor_category_rules
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ============================================================================
-- Comments for Documentation
-- ============================================================================

COMMENT ON TABLE categories IS 'User-defined expense categories for receipt categorization (#{#exp3a})';
COMMENT ON TABLE expense_categories IS 'Receipt to category mapping - expenses derived from receipts (#{#exp1b})';
COMMENT ON TABLE vendor_category_rules IS 'Auto-categorization rules based on vendor patterns (#{#exp4a})';

COMMENT ON COLUMN expense_categories.categorization_source IS 'Source of categorization: manual (user-assigned) or auto (rule-based)';
COMMENT ON COLUMN vendor_category_rules.vendor_pattern IS 'Normalized merchant name for pattern matching';

