export type ReceiptRow = {
	id: string;
	user_id: string;
	receipt_image_path: string | null;
	transaction_date: string | null; // ISO date (YYYY-MM-DD)
	total_amount: number | null;
	tax: number | null;
	merchant_name: string | null;
	credit_card_name: string | null;
	credit_card_last_4: string | null;
	currency: string | null;
	exchange_rate_to_cad: number | null; // #{#fcr1a} Bank of Canada rate for transaction_date
	matched_transaction_id: string | null;
	created_at: string;
	suspicious_date: boolean; // #{#dtv1b} - Flag for dates >42 days old or future
	split_group_id?: string | null; // #{#spl1b} - Links receipts split from the same original
	original_filename: string | null; // #{#ofn1a} - Original filename at time of upload (display-only)
};

export class Receipt {
	#id: string;
	#userId: string;
	#imagePath: string | null;
	#transactionDate: string | null;
	#totalAmount: number | null;
	#tax: number | null;
	#merchantName: string | null;
	#creditCardName: string | null;
	#creditCardLast4: string | null;
	#currency: string | null;
	#exchangeRateToCAD: number | null;
	#matchedTransactionId: string | null;
	#createdAt: string;
	#suspiciousDate: boolean;
	#splitGroupId: string | null;
	#originalFilename: string | null;

	private constructor(row: ReceiptRow) {
		this.#id = row.id;
		this.#userId = row.user_id;
		this.#imagePath = row.receipt_image_path;
		this.#transactionDate = row.transaction_date;
		this.#totalAmount = row.total_amount;
		this.#tax = row.tax;
		this.#merchantName = row.merchant_name;
		this.#creditCardName = row.credit_card_name;
		this.#creditCardLast4 = row.credit_card_last_4;
		this.#currency = row.currency;
		this.#exchangeRateToCAD = row.exchange_rate_to_cad;
		this.#matchedTransactionId = row.matched_transaction_id;
		this.#createdAt = row.created_at;
		this.#suspiciousDate = row.suspicious_date;
		this.#splitGroupId = row.split_group_id ?? null;
		this.#originalFilename = row.original_filename;
	}

	static fromRow(row: ReceiptRow) {
		return new Receipt(row);
	}

	toRow(): ReceiptRow {
		return {
