-- This resolves the "ensure_default_family() requires auth.uid()" error

-- Drop and recreate the ensure_default_family function to handle service role context
CREATE OR REPLACE FUNCTION public.ensure_default_family()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid;
  fam_id uuid;
begin
  -- Try to get user_id from auth.uid() first, then from request.jwt.claims set by RPC
  uid := auth.uid();

  -- If auth.uid() is null, try to get it from the session variable set by insert_receipt_with_context
  if uid is null then
    begin
      uid := nullif(current_setting('request.jwt.claims', true), '')::json->>'sub';
    exception
      when others then
        uid := null;
    end;
  end if;

  -- If we still don't have a user_id, we can't proceed
  if uid is null then
    raise exception 'ensure_default_family() requires auth.uid() or request.jwt.claims to be set';
  end if;

  -- Try to find an active default family
  select fm.family_id into fam_id
  from public.family_members fm
  where fm.user_id = uid and fm.status = 'active' and fm.is_default = true
  limit 1;

  if fam_id is not null then
    return fam_id;
  end if;

  -- If no default, try any active membership
  select fm.family_id into fam_id
  from public.family_members fm
  where fm.user_id = uid and fm.status = 'active'
  limit 1;

  if fam_id is not null then
    return fam_id;
  end if;

  -- Create a new family owned by this user and mark membership as default
  insert into public.families (name, created_by) values (null, uid) returning id into fam_id;
  insert into public.family_members (family_id, user_id, role, status, is_default)
  values (fam_id, uid, 'owner', 'active', true)
  on conflict do nothing;

  return fam_id;
end;
$function$;

