 *
 * Helper functions for working with family memberships and default families.
 */

import { supabase } from '$lib/supabaseClient';
import type { FamilyMember } from '$lib/utils/familyMembers';

/**
 * Get the default family ID for the current authenticated user
 *
 * @returns The user's default family ID, or null if not found
 */
export async function getDefaultFamilyId(): Promise<string | null> {
	const {
		data: { user }
	} = await supabase.auth.getUser();

	if (!user) {
		return null;
	}

	const { data: familyMembers } = await supabase
		.from('family_members')
		.select('family_id, is_default, status')
		.eq('user_id', user.id)
		.eq('status', 'active')
		.order('is_default', { ascending: false })
		.limit(1);

	return familyMembers?.[0]?.family_id || null;
}

/**
 * Get all active families for the current authenticated user
 *
 * @returns Array of family IDs the user is an active member of
 */
export async function getActiveFamilyIds(): Promise<string[]> {
	const {
		data: { user }
	} = await supabase.auth.getUser();

	if (!user) {
		return [];
	}

	const { data: familyMembers } = await supabase
		.from('family_members')
		.select('family_id')
		.eq('user_id', user.id)
		.eq('status', 'active');

	return familyMembers?.map((fm) => fm.family_id) || [];
}

